  async claimOutboundMessageForSending(id: number): Promise<boolean> {
    const [claimed] = await db.update(outboundMessages)
      .set({ status: "sending", sendingAt: new Date() })
      .where(and(
        eq(outboundMessages.id, id),
        eq(outboundMessages.status, "queued"),
        or(isNull(outboundMessages.scheduledFor), lte(outboundMessages.scheduledFor, new Date())),
      ))
      .returning({ id: outboundMessages.id });
    return !!claimed;
  }


  async getQueuedMessages(limit: number) {
    return await db.select().from(outboundMessages)
      .where(eq(outboundMessages.status, "queued"))
      .orderBy(asc(outboundMessages.scheduledFor))
      .limit(limit);
  }

  /**
   * Mark stale in-flight messages as failed.
   * Any row that has been in `sending` status for more than 5 minutes is
   * considered to have been lost in a worker crash/restart before its status
   * update landed.  Surface it as `failed` so operators can see it rather
   * than having it silently loop back into the queue.
   * Returns the count of rows that were transitioned.
   */
  async markStaleInFlightMessagesFailed(): Promise<number> {
    const result = await db.execute(sql`
      UPDATE outbound_messages
      SET status = 'failed',
          error  = 'Worker crash detected: message was stuck in sending state for more than 5 minutes'
      WHERE status = 'sending'
        AND sending_at < NOW() - INTERVAL '5 minutes'
    `);
    return (result as any).rowCount ?? 0;
  }


  async getOutboundStats(campaignId: number) {
    const result = await db.select({
      sent: sql<number>`count(*) filter (where ${outboundMessages.status} = 'sent' or ${outboundMessages.status} = 'delivered' or ${outboundMessages.status} = 'opened' or ${outboundMessages.status} = 'replied')`,
      opened: sql<number>`count(*) filter (where ${outboundMessages.status} = 'opened' or ${outboundMessages.status} = 'replied')`,
      replied: sql<number>`count(*) filter (where ${outboundMessages.status} = 'replied')`,
      bounced: sql<number>`count(*) filter (where ${outboundMessages.status} = 'bounced')`,
    }).from(outboundMessages).where(eq(outboundMessages.campaignId, campaignId));
    return result[0] ?? { sent: 0, opened: 0, replied: 0, bounced: 0 };
  }

  /**
   * Return messages that are stuck in `sending` status for more than 60 seconds.
   * These are in-flight rows that may have been orphaned by a worker crash before
   * the 5-minute stale-cleanup fires.  Surfacing them early lets operators
   * investigate a partial failure before it turns into a failure flood.
   */
  async getStuckSendingMessages() {
    return await db.select().from(outboundMessages)
      .where(
        and(
          eq(outboundMessages.status, "sending"),
          lt(outboundMessages.sendingAt, sql`NOW() - INTERVAL '60 seconds'`),
        )
      )
      .orderBy(asc(outboundMessages.sendingAt));
  }

